review_comments.body:
Rewrite using a set.

function mergeParameters(
  pathItemParams: OpenApiParameters[],
  operationParams: OpenApiParameters[],
): OpenApiParameters[] {
  const map = new Map<string, OpenApiParameters>();
  const key = (p: OpenApiParameters) => `${p.name}:${p.in}`;

  for (const param of pathItemParams) {
    map.set(key(param), param);
  }

  for (const param of operationParams) {
    map.set(key(param), param); // overrides automatically
  }

  return [...map.values()];
}

